import sys

class Solver:

	def __init__(self, num_chefs):
		self.num_chefs = num_chefs
		self.ratings = [[0 for x in range(num_chefs)] for y in range(num_chefs)]
		self.mst = [[0 for x in range(num_chefs)] for y in range(num_chefs)]
		self.visited_nodes = [0 for x in range(num_chefs)]
		self.answer = -1

	def read_ratings(self):
		for num in range(self.num_chefs):
			self.ratings[num] = list(map(int, input().split()))

	def check_ratings(self):
		chef_a = 0
		for chefRating in self.ratings:
			if len(chefRating) != self.num_chefs:
				raise ValueError(f'Chef {chef_a} has not given rating to all chefs')
			for chef_b in range(len(chefRating)):
				if self.ratings[chef_a][chef_b] != self.ratings[chef_b][chef_a]:
					raise ValueError(f'Chef ratings is not symmetric {chef_a} {chef_b}')
				if self.ratings[chef_a][chef_b] < 0:
					raise ValueError(f'Chef rating is not a non-negative integer {chef_a} {chef_b}')
			chef_a += 1

	def solve(self):
		self.answer = -1
		if self.num_chefs == 1:
			if self.ratings[0][0] != 0:
				self.answer = self.ratings[0][0]
			return
		self.find_minimum_spanning_tree()
		if sum(self.visited_nodes) == len(self.visited_nodes):
			self.answer = self.get_sum_of_mst()

	def find_minimum_spanning_tree(self):
		next_node = 0
		self.visited_nodes[next_node] = 1
		while next_node != -1:
			(prev_node, next_node) = self.pick_next_node()
			if next_node != -1:
				self.mst[prev_node][next_node] = self.ratings[prev_node][next_node]
				self.mst[next_node][prev_node] = self.ratings[next_node][prev_node]
				self.visited_nodes[next_node] = 1

	def pick_next_node(self):
		min_weight = sys.maxsize
		prev_node = -1
		next_node = -1
		for from_node in range(self.num_chefs):
			if self.visited_nodes[from_node] == 1:
				for to_node in range(self.num_chefs):
					if from_node != to_node and self.visited_nodes[to_node] == 0:
						weight = self.ratings[from_node][to_node]
						if weight != 0 and weight < min_weight:
							min_weight = weight
							prev_node = from_node
							next_node = to_node
		return (prev_node, next_node)

	def get_sum_of_mst(self):
		sum = 0
		for row in self.mst:
			for num in row:
				sum += num
		return sum

	def write_answer(self):
		print(self.answer)

def main():
	solve()

